inputs.script:
let table = base.getTable("Email Accounts");
let record = await table.selectRecordAsync(input.config().recordId);
let webhook = "https://hook.us1.make.com/REDACTED_PATH";

// Create payload from record fields
let payload = Object.fromEntries(
    table.fields.map(f => [f.name, record.getCellValue(f.name)])
);

// Add the record ID
payload.recordId = record.id;

// Send data to webhook
await fetch(webhook, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
});
